/** Typed fetchers (0001 §3.1, 0002 §2). */
export type Fetch = {
    kind: "github_release";
    repo: string;
    asset: string;
    version?: string;
    sha256?: string;
    baseUrl?: string;
} | {
    kind: "tarball";
    url: string;
    sha256?: string;
} | {
    kind: "git";
    url: string;
    rev: string;
} | {
    kind: "file";
    path: string;
} | {
    kind: "plugin";
    name: string;
    args?: Record<string, unknown>;
} | {
    kind: "brew";
    formula: string;
    sha256?: string;
} | {
    kind: "pixi";
    package: string;
    version?: string;
    sha256?: string;
};
export declare function githubRelease(spec: {
    repo: string;
    asset: string;
    version?: string;
    sha256?: string;
    baseUrl?: string;
}): Fetch;
export declare function tarball(url: string, sha256?: string): Fetch;
export declare function git(url: string, rev: string): Fetch;
export declare function fileFetch(path: string): Fetch;
/** A fetcher plugin transport (0002 §4) — `gripfetch-<name>`. */
export declare function pluginFetch(name: string, args?: Record<string, unknown>): Fetch;
/** A Homebrew bottle — resolved from the formula JSON, so the pin
 *  needs no download at update time. */
export declare function brew(formula: string): Fetch;
/** A conda package via pixi, isolated PIXI_HOME, harvested to store. */
export declare function pixi(pkg: string, version?: string): Fetch;
